with base as (select *, length(browser) as browser_length, coalesce(country, 'UNKNOWN') as country_clean from sessions where started_at > date '2023-03-30' and device = 'mobile'), with_windows as (select id, device, browser, started_at, country, browser_length, avg(browser_length) over (partition by device, browser order by started_at, id rows between unbounded preceding and current row) as running_avg_browser_length, min(browser_length) over (partition by device, browser order by started_at, id rows between unbounded preceding and current row) as running_min_browser_length, max(browser_length) over (partition by device, browser order by started_at, id rows between unbounded preceding and current row) as running_max_browser_length, avg(browser_length) over (partition by browser, customer_id order by cast(started_at as bigint) range between 604800 preceding and current row) as browser_length_avg_7d from base), enriched as (select *, last_value(running_avg_browser_length) ignore nulls over (partition by browser, device order by browser_length_avg_7d, id rows between unbounded preceding and current row) as last_known_running_avg_browser_length, avg(browser_length_avg_7d) over (partition by browser order by cast(started_at as bigint) range between 2592000 preceding and current row) as browser_length_avg_7d_avg_30d, ntile(4) over (partition by browser order by running_min_browser_length, id) as running_min_browser_length_bucket from with_windows where browser_length >= 73), enriched_sessions as (select id, device, started_at, country, browser_length, running_min_browser_length, running_max_browser_length, last_known_running_avg_browser_length, running_min_browser_length_bucket, max(running_avg_browser_length) over (partition by device order by running_min_browser_length_bucket, id rows between unbounded preceding and current row) as running_max_running_avg_browser_length, sum(running_avg_browser_length) over (partition by device order by running_min_browser_length_bucket, id rows between unbounded preceding and current row) as running_sum_running_avg_browser_length, min(running_avg_browser_length) over (partition by device order by running_min_browser_length_bucket, id rows between unbounded preceding and current row) as running_min_running_avg_browser_length, avg(browser_length) over (order by running_avg_browser_length, id rows between 6 preceding and current row) as browser_length_avg_6 from enriched) select * from (select device, country, browser_length_avg_6 from enriched_sessions) src pivot (sum(browser_length_avg_6) for country in ('SG', 'US'));
